// План specs/audit-log.md, 2.1 (кейс AL-04). Admin-dispatcher компании test. Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { DASHBOARD_URL, expectNoAdminPanel, sectionTab, waitForMenu } from '../admin-access/access-helpers';

test.use({ storageState: '../auth/dispatcher.json' });

test.describe('Admin Panel — доступ не супер-админа (#fc4fa4)', () => {
  test('Admin-dispatcher has no Admin Panel in the menu and /adminpanel redirects to the dashboard #fc4fa4 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');

    await page.goto('/dashboard');
    await waitForMenu(page);
    await expect(page.getByRole('link', { name: 'Admin Panel', exact: true })).toHaveCount(0);

    await page.goto('/adminpanel');
    await expect(page).toHaveURL(DASHBOARD_URL);
    await expectNoAdminPanel(page);
    for (const t of ['Coupons', 'Audit log']) await expect(sectionTab(page, t)).toHaveCount(0);
  });
});
